package com.sky.service.impl;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.util.Arrays;
import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import com.sky.entity.OrderDetail;
import com.sky.entity.Orders;
import com.sky.exception.OrderBusinessException;
import com.sky.mapper.OrderDetailMapper;
import com.sky.mapper.OrderMapper;
import com.sky.vo.OrderVO;
import com.sky.constant.MessageConstant;

@ExtendWith(MockitoExtension.class)
class OrderServiceImplTest {

    @InjectMocks
    private OrderServiceImpl orderService;

    @Mock
    private OrderMapper orderMapper;

    @Mock
    private OrderDetailMapper orderDetailMapper;

    @Test
    @DisplayName("正向测试：当订单存在时，details方法应返回正确的OrderVO")
    void testDetails_WhenOrderExists_ShouldReturnOrderVO() {
        // Arrange
        Long orderId = 1L;
        Orders orders = new Orders();
        orders.setId(orderId);
        orders.setNumber("ORDER001");

        List<OrderDetail> orderDetails = Arrays.asList(new OrderDetail(), new OrderDetail());

        when(orderMapper.getById(orderId)).thenReturn(orders);
        when(orderDetailMapper.getByOrderId(orderId)).thenReturn(orderDetails);

        // Act
        OrderVO result = orderService.details(orderId);

        // Assert
        assertNotNull(result);
        assertEquals(orderId, result.getId());
        assertEquals("ORDER001", result.getNumber());

        // Verify
        verify(orderMapper).getById(orderId);
        verify(orderDetailMapper).getByOrderId(orderId);
    }

    @Test
    @DisplayName("边界测试：当订单不存在时，details方法应抛出OrderBusinessException（修复后的行为）")
    void testDetails_WhenOrderDoesNotExist_ShouldThrowOrderBusinessException() {
        // Arrange
        Long orderId = 999L;
        when(orderMapper.getById(orderId)).thenReturn(null);

        // Act & Assert
        OrderBusinessException exception = assertThrows(OrderBusinessException.class, 
            () -> orderService.details(orderId));

        assertEquals(MessageConstant.ORDER_NOT_FOUND, exception.getMessage());

        // Verify
        verify(orderMapper).getById(orderId);
        verifyNoInteractions(orderDetailMapper);
    }

    @Test
    @DisplayName("空值测试：当传入null时，details方法应处理null并抛出OrderBusinessException")
    void testDetails_WhenIdIsNull_ShouldHandleNullGracefully() {
        // Arrange
        when(orderMapper.getById(null)).thenReturn(null);

        // Act & Assert
        OrderBusinessException exception = assertThrows(OrderBusinessException.class, 
            () -> orderService.details(null));

        assertEquals(MessageConstant.ORDER_NOT_FOUND, exception.getMessage());

        // Verify
        verify(orderMapper).getById(null);
        verifyNoInteractions(orderDetailMapper);
    }
}
